#include <windows.h>
#include <stdio.h>
#include "../../src/lib-win32-style/appearance/msstyles/raster_font.h"
#define CHECK(x) do{if(!(x)){fprintf(stderr,"FONT_ISOLATION_FAIL line=%d %s\n",__LINE__,#x);return 1;}}while(0)
int main(void){HFONT source=CreateFontW(-18,0,0,0,FW_NORMAL,FALSE,FALSE,FALSE,DEFAULT_CHARSET,OUT_DEFAULT_PRECIS,CLIP_DEFAULT_PRECIS,DEFAULT_QUALITY,DEFAULT_PITCH,L"Arial");CHECK(source);HFONT shared=style_raster_font_acquire(source,12);CHECK(shared&&shared!=source);HFONT independent=style_raster_font_acquire_isolated(source,12);CHECK(independent&&independent!=source&&independent!=shared);CHECK(style_raster_font_source(independent)==source);HFONT again=style_raster_font_acquire(source,12);CHECK(again==shared);CHECK(style_raster_font_try_retain(independent));style_raster_font_release(independent);style_raster_font_release(again);style_raster_font_release(shared);LOGFONTW lf;CHECK(GetObjectW(independent,sizeof(lf),&lf)==sizeof(lf));style_raster_font_release(independent);CHECK(!GetObjectW(independent,sizeof(lf),&lf));CHECK(DeleteObject(source));puts("STATUS_FONT_ISOLATION_OK shared=1 independent=1 retain=1 cleanup=1");return 0;}
